import { Link } from "react-router-dom";

export default function TermsAndConditions() {
  return (
    <div className="max-w-4xl mx-auto px-4 py-10 text-[#2D1E16]">
      <Link to="/" className="text-[#06d2d9] font-semibold">← Back to Home</Link>
      <h1 className="font-display text-3xl font-bold mt-4">Terms & Conditions</h1>
      <div className="mt-6 space-y-4 text-sm leading-7 text-[#5C4A3D]">
        <p>By placing an order with SLV Bakery, you agree to these terms and conditions.</p>
        <p>All orders are subject to availability. We reserve the right to cancel or modify orders if the requested items are unavailable or if payment verification fails.</p>
        <p>Customers are responsible for providing accurate delivery details, including address, phone number, and delivery timing.</p>
        <p>Orders may be cancelled by the customer before preparation begins. Once preparation has started, cancellations may be subject to a partial refund depending on the status of the order.</p>
        <p>SLV Bakery is not liable for delays caused by weather, traffic, or circumstances beyond our control.</p>
      </div>
    </div>
  );
}
